window.MIL_EVENTS=window.MIL_EVENTS||{},window.MIL_EVENTS["Marine Raiders"]=[{t:"A&S Day One",tier:"junior",i:"compass",d:"Assessment and Selection starts with a ruck run in the North Carolina heat. Half the class looks like they already regret it. How do you start?",c:[{l:"Set a hard pace",p:.6,w:{perf:12,h:-3},wt:"You finish near the front. A cadre member writes something down.",f:{h:-10,perf:-5},ft:"You blow up at mile six and limp in at the back."},{l:"Stay steady, mid-pack",w:{perf:5},wt:"You finish strong and unremarkable. In A&S, that's a win."},{l:"Help a struggling candidate",p:.7,w:{perf:8,rel:10},wt:"Cadre notice you carrying someone else's water. Team players get remembered.",f:{perf:-6},ft:"You both come in late. Nobody remembers why."}]},{t:"The Unknown Distance",tier:"junior",i:"compass",d:"The cadre won't say how far today's ruck is. It's been four hours. Rumor says it never ends. What's your mindset?",c:[{l:"One step at a time",p:.75,w:{perf:10,h:-4},wt:"You stop counting and keep moving. Turns out it was 18 miles.",f:{h:-8},ft:"Your feet bleed through your socks but you finish. Barely."},{l:"Ask a cadre how far",p:.2,w:{perf:2},wt:"He actually tells you. You're stunned.",f:{perf:-8},ft:"'As far as it takes, candidate.' He writes your number down."},{l:"Consider dropping (DOR)",w:{perf:-20,sm:-10},wt:"You think about it hard, then don't. The doubt costs you, though."}]},{t:"Psych Board",tier:"junior",i:"laptop",d:"A psychologist asks why you want to be a Raider and how you handle failure. Your answer could decide your career. What do you say?",c:[{l:"Honest and humble",p:.8,w:{perf:8,sm:3},wt:"You talk about your failures plainly. The psych nods. Good sign.",f:{perf:-3},ft:"You ramble. The psych's face gives nothing away."},{l:"Movie-hero answer",p:.3,w:{perf:3},wt:"Somehow it lands.",f:{perf:-10},ft:"'So you want to be in a movie?' Not great."},{l:"Talk about your team",p:.7,w:{perf:10},wt:"You say Raiders are a team sport. The board loves it.",f:{perf:-2},ft:"It sounds rehearsed because it is."}]},{t:"Team Event Sandbag",tier:"junior",i:"helmet",d:"Your A&S team must carry a waterlogged log and sandbags across a swamp. Your teammate {buddy} keeps letting go. How do you handle it?",c:[{l:"Quietly pick up his slack",p:.7,w:{perf:8,h:-5,rel:8},wt:"Cadre see you take more weight without complaining.",f:{h:-12},ft:"Your back tweaks under the extra load."},{l:"Call him out loudly",p:.5,w:{perf:4,rel:-10},wt:"He grips tighter. It works, but he hates you.",f:{perf:-6,rel:-15},ft:"The cadre mark you as a poor teammate."},{l:"Rotate positions",p:.8,w:{perf:10},wt:"You organize a rotation. Leadership noticed.",f:{perf:-2},ft:"The rotation falls apart in the mud."}]},{t:"Selected",tier:"junior",i:"trident",d:"Your name is read at the end of A&S. You're going to the Individual Training Course. A cadre shakes your hand. How do you celebrate?",c:[{l:"Call your family",w:{h:5,sm:3},wt:"Your mom cries. Your dad pretends he isn't."},{l:"Eat everything in sight",w:{h:8},wt:"You eat three burgers and a whole pizza. No regrets."},{l:"Sleep for 14 hours",w:{h:10},wt:"You wake up still in your boots."}]},{t:"ITC Close Quarters",tier:"junior",i:"gun",d:"Shoot house day at ITC. You're number two through the door, and the room has hostages and targets mixed together. What's your approach?",c:[{l:"Fast and aggressive",p:.55,w:{perf:12},wt:"Clean hits, zero hostages tagged. Instructor grunts approval.",f:{perf:-10},ft:"You put two rounds into a hostage target. Long debrief."},{l:"Controlled and deliberate",p:.8,w:{perf:8},wt:"Slower, but perfect. That's what they want.",f:{perf:-4},ft:"Too slow. The number one man is clearing your corner."},{l:"Follow the man in front",p:.6,w:{perf:5},wt:"You flow off him smoothly.",f:{perf:-6},ft:"You both end up looking at the same corner."}]},{t:"SERE Phase",tier:"junior",i:"skull",d:"You're 'captured' during SERE training. The interrogator is very convincing and you haven't slept in a day. How do you hold up?",c:[{l:"Stick to the code",p:.7,w:{perf:10,sm:2},wt:"You give nothing beyond what's allowed. You'll never forget this week.",f:{perf:-5,h:-5},ft:"You say something you shouldn't have. Instructors note it."},{l:"Crack a joke",p:.3,w:{perf:3},wt:"The interrogator almost smiles.",f:{h:-6},ft:"He does not find you funny. More stress positions."},{l:"Go silent",p:.6,w:{perf:7},wt:"Silence works. You survive.",f:{perf:-3},ft:"Silence made them work harder on you."}]},{t:"Language Class",tier:"junior",i:"laptop",d:"ITC assigns you a language for foreign internal defense work. Classes run late after long days. How hard do you study?",c:[{l:"Flashcards every night",p:.8,w:{sm:6,perf:6},wt:"You can order food and ask for a village elder. Progress.",f:{h:-4},ft:"You're exhausted and still mixing up verbs."},{l:"Bare minimum",w:{perf:-3},wt:"You pass. Barely. Interpreters will love you."},{l:"Practice with a native speaker",p:.7,w:{sm:8,perf:8},wt:"A local shop owner becomes your tutor. Huge improvement.",f:{sm:2},ft:"He mostly teaches you slang and insults."}]},{t:"Raider Heritage",tier:"junior",i:"flag",d:"An old instructor tells you about the 1942 Makin Island raid, launched from submarines. He asks what 'Spiritus Invictus' means to you. Your answer?",c:[{l:"Unconquerable spirit",w:{perf:4,sm:3},wt:"He nods. 'Now earn it.'"},{l:"Never quit",w:{perf:3},wt:"'Close enough,' he says. 'Don't forget it.'"},{l:"Shrug",w:{perf:-5},wt:"He stares at you until you feel very small."}]},{t:"The Raider Pin",tier:"junior",i:"trident",d:"ITC graduation. You're now a Critical Skills Operator. {buddy} pins you and grins. What do you do afterward?",c:[{l:"Toast the fallen Raiders",w:{sm:4,rel:10},wt:"Your team raises a glass in silence. It hits harder than you expected."},{l:"Party in Jacksonville",p:.7,w:{h:4,rel:8},wt:"Great night, nothing broken, nobody arrested.",f:{njp:1,perf:-8},ft:"A bar fight on graduation night. Your commander is not impressed."},{l:"Fly home",w:{h:6},wt:"Your hometown treats you like a celebrity for a weekend."}]},{t:"New Guy Duties",tier:"junior",i:"tent",d:"You're the new guy on your team in {unit}. Someone has to clean the team room, inventory gear, and make coffee. Guess who. Your attitude?",c:[{l:"Do it without a word",w:{perf:6,rel:6},wt:"Senior guys notice. The coffee is also good."},{l:"Complain in the group chat",w:{perf:-6,rel:-8},wt:"Everyone saw it. Including the team chief."},{l:"Make it a competition",p:.6,w:{rel:10},wt:"You turn inventory into a game. Even the old guys join.",f:{perf:-3},ft:"Nobody plays. You still do it alone."}]},{t:"Dive Pipeline",tier:"junior",i:"trident",d:"You're slotted for combat diver training. Pool comp is legendary: instructors rip off your regulator underwater. How do you face it?",c:[{l:"Stay calm, fix it",p:.65,w:{perf:12},wt:"You methodically untangle everything. Pass.",f:{h:-8,perf:-8},ft:"You panic and bolt for the surface. Fail."},{l:"Train extra beforehand",p:.8,w:{perf:14,h:-2},wt:"Weeks of breath holds pay off. Smooth pass.",f:{perf:-4},ft:"You overtrain and arrive exhausted."},{l:"Ask to delay the course",w:{perf:-5},wt:"You get a later slot. Someone else takes yours."}]},{t:"Jump School Mishap",tier:"junior",i:"jet",d:"On a static line jump, your canopy twists and you're spinning. The ground is coming fast. What do you do?",c:[{l:"Bicycle kick out",p:.75,w:{perf:5},wt:"The twists unwind. You land with a story.",f:{he:-15,h:-10},ft:"You land hard and wreck your ankle."},{l:"Pull the reserve",p:.85,w:{perf:3},wt:"Reserve opens. Rough landing, but you walk away.",f:{he:-20},ft:"Both canopies tangle. You hit hard."},{l:"Freeze",p:.2,w:{lk:5},wt:"The canopy fixes itself. Pure luck.",f:{die:.05,cause:"killed in a parachute malfunction",he:-30},ft:"You hit the ground like a sack of bricks."}]},{t:"Range Brass Detail",tier:"junior",i:"gun",d:"After a 3,000-round day, someone has to police brass in the rain. {buddy} suggests hiding a few bags behind the berm. What do you do?",c:[{l:"Pick it all up",w:{perf:5,h:-2},wt:"Soaked and miserable, but honest."},{l:"Hide the brass",p:.5,w:{h:2,rel:5},wt:"Nobody checks. You go home early.",f:{njp:1,perf:-10},ft:"Range control finds it. Everyone gets smoked, then you get NJP."},{l:"Talk him out of it",w:{rel:-3,perf:3},wt:"He rolls his eyes, but helps."}]},{t:"First Deployment",tier:"junior",i:"map",d:"Your Marine Special Operations Team deploys to {country} to train local forces. On the plane, {buddy} asks if you're nervous. Your answer?",c:[{l:"Admit it",w:{rel:8,sm:2},wt:"He admits he is too. You both feel better."},{l:"'Born ready'",w:{rel:-2},wt:"He laughs. 'Sure, new guy.'"},{l:"Sleep the whole flight",w:{h:5},wt:"Pro move. You land rested."}]},{t:"Partner Force Range",tier:"junior",i:"gun",d:"You're teaching marksmanship to partner soldiers in {country}. One keeps sweeping the line with his muzzle. How do you correct him?",c:[{l:"Calm demonstration",p:.8,w:{perf:6},wt:"He gets it. Nobody dies today.",f:{perf:-2},ft:"He nods and keeps doing it."},{l:"Yell like a drill instructor",p:.4,w:{perf:3},wt:"It works, through translation.",f:{perf:-6},ft:"He's humiliated in front of his unit. Rapport drops."},{l:"Have his sergeant fix it",p:.75,w:{perf:8},wt:"Letting their leaders lead is the whole point of FID.",f:{perf:-2},ft:"His sergeant shrugs. It's a long day."}]},{t:"Tea With the Elder",tier:"junior",i:"tent",d:"A village elder in {country} invites you for tea. It's your third cup and your stomach is not okay. Refusing could be rude. What do you do?",c:[{l:"Drink it",p:.5,w:{perf:6},wt:"Strong rapport. He shares useful information.",f:{h:-10},ft:"You spend two days hugging a latrine."},{l:"Politely decline",p:.6,w:{perf:2},wt:"He understands. Mostly.",f:{perf:-4},ft:"He's offended. The meeting ends early."},{l:"Fake sipping",p:.7,w:{perf:4},wt:"Nobody notices. Diplomacy achieved.",f:{perf:-5},ft:"His grandson notices. Awkward."}]},{t:"Contact Front",tier:"junior",i:"gun",d:"Your patrol takes fire from a tree line in {country}. Partner forces scatter. {buddy} is pinned behind a low wall. What do you do?",c:[{l:"Lay down covering fire",p:.7,w:{perf:10,rel:12},wt:"{buddy} sprints to cover. The enemy breaks contact.",f:{wound:1},ft:"A round finds you as you rise up to shoot."},{l:"Rally the partner force",p:.5,w:{perf:14},wt:"You get them firing back. The ambush collapses.",f:{wound:1},ft:"You get hit running between positions."},{l:"Call for support",p:.8,w:{perf:8},wt:"Mortars land on the tree line. Contact over.",f:{perf:-4},ft:"Support is 30 minutes out. It's a long 30 minutes."}]},{t:"Night Vision Fail",tier:"junior",i:"helmet",d:"Your NVG battery dies halfway through a night movement. It's pitch black and silence is critical. What now?",c:[{l:"Swap batteries by feel",p:.7,w:{perf:5},wt:"You practiced this blindfolded. It pays off.",f:{perf:-5},ft:"You drop the spare. It's gone forever."},{l:"Grab the man ahead's pack",w:{perf:1},wt:"You follow by touch. Embarrassing but effective."},{l:"Use a flashlight",p:.2,w:{perf:1},wt:"Nobody saw it. You got lucky.",f:{perf:-12,rel:-10},ft:"The whole team hisses at you. Never again."}]},{t:"IED Lane",tier:"junior",i:"bomb",d:"On a foot patrol, you spot disturbed dirt and a wire near the path. The team is 20 meters behind you. What do you do?",c:[{l:"Freeze and call it out",p:.9,w:{perf:10},wt:"EOD confirms an IED. You may have saved lives.",f:{perf:2},ft:"It's a buried cable. Better safe than sorry."},{l:"Inspect it yourself",p:.4,w:{perf:6},wt:"Just trash. You got lucky.",f:{wound:1,die:.15,cause:"killed by an IED"},ft:"It detonates."},{l:"Detour around",p:.7,w:{perf:4},wt:"You reroute safely.",f:{wound:1},ft:"The detour had a second device."}]},{t:"Morning PT Smoke",tier:"junior",i:"helmet",d:"Your team chief runs a PT session that leaves everyone puking. {buddy} says you should complain to the officer. What do you do?",c:[{l:"Suck it up",w:{h:4,perf:3},wt:"Next week, you're the one not puking."},{l:"Complain",w:{perf:-6},wt:"The officer laughs and tells the chief. The next PT is worse."},{l:"Ask the chief to program it",p:.6,w:{perf:6},wt:"He's impressed you care. You help plan PT now.",f:{perf:-2},ft:"'You want programming? Do burpees.'"}]},{t:"Liberty in Okinawa",tier:"junior",i:"star",d:"On a stopover in Okinawa, {buddy} wants to hit Gate 2 Street after curfew. The liberty rules are strict. Do you go?",c:[{l:"Stay in",w:{h:3},wt:"You hear the next morning that a bunch of guys got caught."},{l:"Go out",p:.4,w:{h:5,rel:10},wt:"Best night of the deployment.",f:{njp:1,perf:-12},ft:"Shore patrol catches you after curfew. NJP."},{l:"Go but leave early",p:.75,w:{rel:5},wt:"You get back in time. Responsible fun.",f:{perf:-5},ft:"The taxi gets lost. You're 10 minutes late."}]},{t:"Social Media Post",tier:"junior",i:"laptop",d:"You want to post a photo of your kit and team on social media. It looks very cool. What do you do?",c:[{l:"Post it",w:{perf:-15,rel:-10},wt:"The team's faces are visible. OPSEC brief, in person, loudly."},{l:"Blur faces and post",p:.6,w:{sm:1},wt:"Gets a ton of likes and no trouble.",f:{perf:-8},ft:"The geotag showed your base. Oops."},{l:"Don't post it",w:{perf:2},wt:"Smart. The best operators are boring online."}]},{t:"Sniper Course Slot",tier:"junior",i:"bullseye",d:"One slot is open for a sniper course. You and {buddy} both want it. The team chief asks you to make your case. What do you do?",c:[{l:"Show your range data",p:.6,w:{perf:8},wt:"Your numbers win. You get the slot.",f:{perf:-2},ft:"His numbers are better."},{l:"Give it to {buddy}",w:{rel:15,perf:2},wt:"He never forgets it. Next slot is yours."},{l:"Badmouth him",p:.3,w:{perf:3,rel:-20},wt:"You get it. He knows what you did.",f:{perf:-8,rel:-20},ft:"The chief sees right through it."}]},{t:"Sniper Stalk",tier:"junior",i:"bullseye",d:"During a sniper stalk, an instructor walks within three feet of your ghillie suit. Your nose itches terribly. What do you do?",c:[{l:"Don't move at all",p:.75,w:{perf:10},wt:"He walks past. You take your shot. Pass.",f:{perf:-4},ft:"He spots the barrel glint anyway."},{l:"Scratch very slowly",p:.35,w:{perf:5},wt:"Somehow, you get away with it.",f:{perf:-8},ft:"'Got you.' The instructor taps your head."}]},{t:"Injury at Training",tier:"junior",i:"stethoscope",d:"You tear something in your shoulder during fast-rope training. Reporting it could cost you a deployment. What do you do?",c:[{l:"Report it",w:{he:5,perf:-4},wt:"Surgery and rehab. You'll be back."},{l:"Hide it",p:.35,w:{perf:3},wt:"It heals on its own. You dodged a bullet.",f:{he:-25},ft:"It fully tears on deployment. Now it's surgery and a long rehab."},{l:"Ask the team corpsman quietly",p:.7,w:{he:4},wt:"He sets you up with a physical therapy plan.",f:{he:-6},ft:"He reports it anyway. Medical hold."}]},{t:"Fast Rope Burn",tier:"junior",i:"helicopter",d:"Fast-roping from a hovering helicopter at night, your gloves start smoking. The ground's about 20 feet down. What do you do?",c:[{l:"Grip tighter",p:.6,w:{perf:4},wt:"Your palms sting but you land fine.",f:{he:-10},ft:"You burn through and drop the last 10 feet."},{l:"Use your boots more",p:.8,w:{perf:6},wt:"Textbook. You land soft.",f:{he:-6},ft:"Your feet slip. Rough landing."}]},{t:"Barracks Inspection",tier:"junior",i:"star",d:"Surprise room inspection. Your roommate {buddy} has energy drinks and protein powder all over the floor. What's your move?",c:[{l:"Speed clean his mess",p:.7,w:{rel:10},wt:"You pass with seconds to spare. He owes you.",f:{perf:-4},ft:"The sergeant walks in mid-cleanup."},{l:"Let him take the hit",w:{rel:-8},wt:"He gets yelled at. You're fine."}]},{t:"Gear Sale",tier:"junior",i:"recycle",d:"{buddy} says you can sell spare issued gear online for good money. 'Nobody counts it,' he says. What do you do?",c:[{l:"Refuse",w:{perf:3},wt:"Two months later, he's under investigation."},{l:"Sell it",p:.3,w:{money:1500},wt:"Easy money. Your stomach still turns.",f:{court:"theft of government property",discharge:"general"},ft:"NCIS finds the listings. Career over."}]},{t:"Tattoo Decision",tier:"junior",i:"dagger",d:"{buddy} wants to get matching Raider skull tattoos the night after graduation. Do you join?",c:[{l:"Get it",w:{rel:12,h:2},wt:"It looks great. Your mom does not agree."},{l:"Get something subtle",w:{rel:4},wt:"Small and classy. You'll thank yourself at 50."},{l:"Skip it",w:{rel:-4},wt:"He calls you boring for a week."}]},{t:"Desert Navigation",tier:"junior",i:"compass",d:"During a land nav event in the desert, your GPS dies and the terrain all looks the same. Water is running low. What do you do?",c:[{l:"Map and compass",p:.75,w:{perf:8},wt:"Old school skills win. You hit every point.",f:{h:-10},ft:"You walk five miles in the wrong direction."},{l:"Head for high ground",p:.6,w:{perf:5},wt:"You spot a landmark and reorient.",f:{h:-8},ft:"The climb drains your water."},{l:"Wait for pickup",w:{perf:-8},wt:"You fail the event, but you're alive."}]},{t:"Water Survival",tier:"junior",i:"trident",d:"During water confidence training, you have to tread water in full kit for 10 minutes. Your arms burn. What do you do?",c:[{l:"Push through",p:.7,w:{perf:8,h:-2},wt:"You finish. The instructor nods.",f:{h:-10},ft:"They pull you out sputtering."},{l:"Ditch gear smartly",p:.8,w:{perf:6},wt:"You drop what you're allowed to. Smart.",f:{perf:-5},ft:"You dropped the rifle. Not allowed."}]},{t:"Team Chief Choice",tier:"nco",i:"star",d:"As {rank} you've been asked to take over as team chief. It means more paperwork and less trigger time. Do you accept?",c:[{l:"Accept",w:{perf:10,h:-2},wt:"Your team trusts you. You lose sleep and gain gray hairs."},{l:"Turn it down",w:{perf:-5},wt:"You keep shooting, but the command remembers."},{l:"Accept with conditions",p:.5,w:{perf:8},wt:"Your CO agrees to keep you in the field.",f:{perf:-4},ft:"'This isn't a negotiation, {rank}.'"}]},{t:"Training the Partner NCOs",tier:"nco",i:"flag",d:"Partner force NCOs in {country} defer every decision to their officers. You want them leading. How do you build that?",c:[{l:"Run NCO-led drills",p:.7,w:{perf:10},wt:"A partner sergeant runs a perfect patrol. Huge win.",f:{perf:-4},ft:"Their officers feel undermined and shut it down."},{l:"Work through their officers",p:.8,w:{perf:8},wt:"Slow but lasting. The officers buy in.",f:{perf:-2},ft:"Progress is glacial."},{l:"Do it yourself",w:{perf:-6},wt:"Things work while you're there. Not after."}]},{t:"Corrupt Partner Commander",tier:"nco",i:"policeman",d:"You discover the partner force commander in {country} is selling fuel you provided on the black market. What's your move?",c:[{l:"Report up the chain",p:.75,w:{perf:10},wt:"Your command addresses it diplomatically. He's replaced.",f:{perf:-4},ft:"Nothing happens. He knows you reported him."},{l:"Confront him directly",p:.4,w:{perf:6},wt:"He stops. Respect earned.",f:{perf:-10},ft:"He freezes your team out of all operations."},{l:"Ignore it",w:{perf:-6,sm:-2},wt:"The mission continues. Your conscience doesn't sleep well."}]},{t:"Direct Action Raid",tier:"nco",i:"gun",d:"Night raid on a compound in {country}. The breach charge fails to fire. Dogs are barking. Your team is stacked at the door. What now?",c:[{l:"Mechanical breach",p:.7,w:{perf:12},wt:"The door gives on the third hit. Target captured.",f:{wound:1},ft:"Someone inside fires through the door."},{l:"Find another entry",p:.6,w:{perf:14},wt:"Window entry catches them totally off guard.",f:{perf:-6},ft:"The target escapes out the back."},{l:"Re-prime the charge",p:.8,w:{perf:10},wt:"Second charge works. Clean raid.",f:{wound:1},ft:"The delay gives them time to prepare."}]},{t:"HVT Positive ID",tier:"nco",i:"bullseye",d:"You're watching a man you think is your high-value target. Facial match is 70%. The window closes in minutes. Your call?",c:[{l:"Wait for better ID",p:.6,w:{perf:10},wt:"He turns. Confirmed match. Clean capture.",f:{perf:-6},ft:"He drives off. Window lost."},{l:"Move now",p:.5,w:{perf:14},wt:"It's him. The team takes him without a shot.",f:{perf:-12,sm:-4},ft:"Wrong man. A very awkward release and apology."},{l:"Ask for higher guidance",w:{perf:2},wt:"Your commander makes the call and owns it."}]},{t:"Special Reconnaissance",tier:"nco",i:"satellite",d:"You've been in a hide site watching a smuggling route for four days. A goat herder is walking straight toward your position. What do you do?",c:[{l:"Stay still",p:.6,w:{perf:12},wt:"He passes within 10 feet. Never sees you.",f:{perf:-10},ft:"His dog finds you. Mission compromised, exfil early."},{l:"Quietly relocate",p:.7,w:{perf:8},wt:"You slip away and set up again.",f:{perf:-6},ft:"Rock slide. He definitely heard that."},{l:"Call early exfil",w:{perf:-4},wt:"Safe, but you lose the observation."}]},{t:"Ambush Survivor",tier:"nco",i:"fire",d:"Your vehicle convoy is hit by an IED followed by heavy machine gun fire. The lead vehicle is burning with men inside. What do you do?",c:[{l:"Pull them out",p:.55,w:{perf:15,medal:"Bronze Star",rel:20},wt:"You drag two men from the flames under fire.",f:{wound:1,die:.12,cause:"killed during a convoy ambush"},ft:"You're hit reaching the vehicle."},{l:"Suppress the gun",p:.65,w:{perf:12},wt:"Your fire silences the gun. Others pull the men free.",f:{wound:1},ft:"A round finds you behind the turret."},{l:"Call CAS",p:.75,w:{perf:8},wt:"Jets arrive. The enemy breaks off.",f:{perf:-6},ft:"Air is 20 minutes out. Too long."}]},{t:"Silver Star Moment",tier:"nco",i:"medal",d:"Your team is overrun at an outpost. You're the senior Marine left standing. Ammunition is low. How do you fight?",c:[{l:"Counterattack",p:.35,w:{perf:20,medal:"Silver Star"},wt:"Your counterattack shatters the assault. The outpost holds.",f:{wound:1,die:.25,cause:"killed defending an outpost"},ft:"You're cut down leading the charge."},{l:"Consolidate and hold",p:.6,w:{perf:14,medal:"Bronze Star"},wt:"You hold until the QRF arrives.",f:{wound:1},ft:"You hold, but take shrapnel."},{l:"Fall back",p:.7,w:{perf:4},wt:"Everyone gets out alive.",f:{perf:-10},ft:"The retreat is chaotic. Equipment is left behind."}]},{t:"Medevac Under Fire",tier:"nco",i:"helicopter",d:"{buddy} is badly hit. The medevac bird won't land until the LZ is secured. You have three Marines and a partner squad. What do you do?",c:[{l:"Push the perimeter",p:.6,w:{perf:12,rel:15},wt:"LZ goes cold. {buddy} makes it out.",f:{wound:1,rel:5},ft:"You take a round securing it."},{l:"Carry him to an alternate LZ",p:.5,w:{perf:10,rel:20,h:-5},wt:"A 600-meter carry. He lives.",f:{rel:-5,sm:-6},ft:"He doesn't make it. You carry that forever."},{l:"Smoke and pray",p:.4,w:{perf:6},wt:"The pilots come in anyway. Legends.",f:{perf:-8},ft:"The bird takes fire and waves off."}]},{t:"Civilian Casualty",tier:"nco",i:"skull",d:"After a firefight, you find a civilian was killed in crossfire. The partner force wants to leave it out of the report. What do you do?",c:[{l:"Report it accurately",w:{perf:4,sm:2},wt:"It's painful, but right. The family gets compensation."},{l:"Go along with them",p:.5,w:{perf:2},wt:"Nobody asks questions.",f:{court:"false official statement",demote:1},ft:"A drone feed contradicts the report. Investigation."}]},{t:"PTSD Creeping In",tier:"nco",i:"stethoscope",d:"Since your last deployment, fireworks make you hit the ground and you barely sleep. Your spouse is worried. What do you do?",c:[{l:"See a counselor",w:{h:10,sm:3},wt:"It's hard to talk, but it helps. Sleep slowly returns."},{l:"Drink it away",w:{h:-12},wt:"It works for a night. Then it doesn't."},{l:"Talk to {buddy}",p:.8,w:{h:6,rel:10},wt:"He's been through the same. You aren't alone.",f:{h:-2},ft:"He changes the subject. He's not ready either."}]},{t:"Marriage Strain",tier:"nco",i:"flag",d:"You've deployed three times in five years. Your spouse says they feel like a single parent. They want you to consider leaving. What do you do?",c:[{l:"Request a stateside billet",w:{h:6,perf:-4},wt:"Instructor duty. Home every night. Your family breathes."},{l:"Promise to make it work",p:.5,w:{h:3},wt:"You put in the effort. Things improve.",f:{h:-10},ft:"Divorce papers arrive mid-deployment."},{l:"Couples counseling",p:.7,w:{h:8},wt:"Military OneSource helps. You both listen better.",f:{h:-4},ft:"Sessions keep getting canceled for training."}]},{t:"Bad Lieutenant",tier:"nco",i:"star",d:"A new team commander wants to skip rehearsals before a live mission. Your team is uneasy. As senior enlisted, what do you do?",c:[{l:"Push back privately",p:.75,w:{perf:8},wt:"He listens. Rehearsals happen. Mission goes clean.",f:{perf:-4},ft:"He overrules you. The mission gets messy."},{l:"Go over his head",p:.5,w:{perf:4},wt:"The company commander intervenes.",f:{perf:-8},ft:"You've made an enemy for the rest of the tour."},{l:"Run them anyway",p:.7,w:{perf:6,rel:8},wt:"Your team rehearses on their own time. He comes around.",f:{perf:-4},ft:"He calls it insubordination."}]},{t:"Mentor a Young Raider",tier:"nco",i:"trident",d:"A new CSO on your team keeps struggling on the range and is losing confidence. The others are mocking him. What do you do?",c:[{l:"Coach him one-on-one",p:.8,w:{perf:8},wt:"Within a month he's outshooting the mockers.",f:{perf:2},ft:"He improves a little. It's a start."},{l:"Shut the mocking down",w:{perf:5},wt:"The team gets the message. Morale improves."},{l:"Let him sink or swim",w:{perf:-3},wt:"He requests a transfer out. Wasted talent."}]},{t:"Range Accident",tier:"nco",i:"bomb",d:"You're range safety officer for a demolitions range. A junior Marine sets a charge with the wrong time fuse length. What do you do?",c:[{l:"Stop everything",w:{perf:10},wt:"You catch it before anyone gets hurt. Teaching moment."},{l:"Fix it quietly",p:.7,w:{perf:5},wt:"Problem solved without drama.",f:{he:-15},ft:"The charge goes early while you work on it."}]},{t:"Drinking Problem",tier:"nco",i:"skull",d:"{buddy} shows up to morning formation smelling like a brewery for the third time this month. What do you do?",c:[{l:"Get him help",p:.7,w:{rel:10,perf:4},wt:"He enters a program. He's grateful years later.",f:{rel:-10},ft:"He feels betrayed and won't talk to you."},{l:"Cover for him",p:.5,w:{rel:8},wt:"He gets his act together. This time.",f:{perf:-10,rel:-5},ft:"He gets a DUI. Your cover-up comes out."},{l:"Report him",w:{rel:-15,perf:2},wt:"By the book. He's off the team."}]},{t:"Interpreter's Visa",tier:"nco",i:"flag",d:"Your interpreter in {country} has saved your life twice. His family is getting threats. His special visa is stuck in paperwork. What do you do?",c:[{l:"Write letters, push hard",p:.6,w:{sm:5},wt:"Months later, he lands in the US. He sends a photo of his kids.",f:{sm:-5},ft:"The visa is still pending. You stop sleeping well."},{l:"Call your congressman",p:.5,w:{sm:6},wt:"Their office expedites it.",f:{perf:-2},ft:"Your chain of command is annoyed you went outside."},{l:"Accept it's out of your hands",w:{sm:-6},wt:"You never hear from him again."}]},{t:"Boat Infiltration",tier:"nco",i:"trident",d:"You're leading a combat rubber raiding craft insertion. The swells are bigger than forecast and the engine sputters. What do you do?",c:[{l:"Push on",p:.55,w:{perf:12},wt:"You hit the beach on time, soaked.",f:{he:-10,perf:-8},ft:"The boat flips in the surf. Gear lost."},{l:"Abort and reschedule",w:{perf:-2},wt:"Nobody likes it, but nobody drowns."},{l:"Paddle in",p:.7,w:{perf:10,h:-5},wt:"Silent and exhausting. It works.",f:{perf:-6},ft:"You miss the window by an hour."}]},{t:"HALO Jump",tier:"nco",i:"jet",d:"Night HALO jump into {country}. At 25,000 feet your oxygen mask feels loose. The green light is on. What do you do?",c:[{l:"Tighten and go",p:.8,w:{perf:10},wt:"Seal holds. Perfect canopy flight to the DZ.",f:{he:-15},ft:"Hypoxia hits in freefall. You barely pull in time."},{l:"Sit this pass out",w:{perf:-6},wt:"You jump on the second pass and land miles from the team."},{l:"Swap masks with the safety",p:.7,w:{perf:6},wt:"Quick swap. Clean jump.",f:{perf:-4},ft:"The swap takes too long. Jumpmaster is furious."}]},{t:"Deployment Tempo",tier:"nco",i:"map",d:"Your unit wants you for another rotation. You've been home seven months. Your knees are shot and your kid's in kindergarten. What do you do?",c:[{l:"Go",w:{perf:8,h:-6},wt:"The team needs your experience. Your kid sends drawings."},{l:"Ask for a break",p:.6,w:{h:8},wt:"Your sergeant major agrees. You coach T-ball.",f:{perf:-5},ft:"Request denied. Pack your bags."},{l:"Volunteer to instruct",w:{h:6,perf:3},wt:"You go to the schoolhouse. Home for dinner."}]},{t:"Hazing Report",tier:"nco",i:"policeman",d:"You catch a few senior guys making a new operator do humiliating things in the team room. They call it 'tradition'. What do you do?",c:[{l:"Stop it now",w:{perf:8,sm:2},wt:"Uncomfortable for a day. It never happens again."},{l:"Report it",w:{perf:5},wt:"Investigation follows. Some resentment, but it's done."},{l:"Walk away",w:{perf:-8},wt:"It becomes a news story months later. Your name comes up."}]},{t:"Interagency Op",tier:"nco",i:"satellite",d:"You're attached to a government agency team in {country}. Their rules are vague and their requests are sketchy. What do you do?",c:[{l:"Stick to your ROE",w:{perf:6},wt:"They grumble, but respect your lines."},{l:"Go along with them",p:.5,w:{perf:8},wt:"Great results. No questions asked.",f:{court:"violating rules of engagement",demote:1},ft:"An inspector general report lands on your desk."},{l:"Call your commander",w:{perf:4},wt:"Legal sorts it out. Slow but safe."}]},{t:"K9 Partner",tier:"nco",i:"helmet",d:"Your team's assault dog freezes at a doorway and won't go in. The handler is wounded. What do you do?",c:[{l:"Trust the dog",p:.85,w:{perf:10},wt:"Turns out the room was rigged with explosives. Good dog.",f:{perf:-4},ft:"The room was empty. Lost precious time."},{l:"Clear it yourself",p:.4,w:{perf:6},wt:"Empty. Fine.",f:{wound:1,die:.1,cause:"killed by a booby trap"},ft:"Booby trap."}]},{t:"Reenlistment Bonus",tier:"nco",i:"recycle",d:"MARSOC offers a large reenlistment bonus. A defense contractor offers triple your salary. What do you do?",c:[{l:"Reenlist",w:{money:5e4,perf:5},wt:"Bonus banked. Back to the team."},{l:"Take the contractor job",w:{money:2e4,discharge:"honorable"},wt:"Big money. You miss the brotherhood within a month."},{l:"Negotiate a better billet",p:.5,w:{money:5e4,perf:8},wt:"Bonus and your choice of assignment.",f:{money:3e4},ft:"You get a smaller bonus and a desk job."}]},{t:"Lost Rifle",tier:"nco",i:"gun",d:"After a long patrol, a junior Marine on your team realizes his rifle is missing. It's 2 AM. What do you do?",c:[{l:"Search with the whole team",p:.7,w:{perf:4},wt:"Found in the back of a truck. Crisis averted.",f:{perf:-10},ft:"Not found. Investigation, and everyone loses their weekend."},{l:"Report immediately",w:{perf:2},wt:"Painful, but the right move. It's found next day."}]},{t:"Fitness Test",tier:"nco",i:"helmet",d:"You're 34 and the young guys are smoking you on the run. Your PFT is this week. How do you prepare?",c:[{l:"Train smart",p:.75,w:{perf:6,h:3},wt:"First-class score. Old man strength.",f:{h:-4},ft:"You pull a calf muscle the day before."},{l:"Wing it",p:.5,w:{perf:2},wt:"Experience gets you through.",f:{perf:-6},ft:"Second class score. The young guys never let it go."}]},{t:"Partner Force Mutiny",tier:"nco",i:"fire",d:"Partner soldiers you trained refuse to fight after their pay is stolen by their own officers. An operation starts tomorrow. What do you do?",c:[{l:"Push for their pay",p:.6,w:{perf:10},wt:"You get the money released. They fight hard.",f:{perf:-6},ft:"The operation is canceled."},{l:"Go without them",p:.4,w:{perf:8},wt:"Your team does it alone. It works.",f:{wound:1},ft:"You're badly outnumbered."},{l:"Inspire them",p:.3,w:{perf:14},wt:"Your speech actually lands.",f:{perf:-4},ft:"Translation loses everything."}]},{t:"Green-on-Blue Warning",tier:"nco",i:"dagger",d:"A partner soldier has been staring at your team strangely and asking where you sleep. Your gut says something is wrong. What do you do?",c:[{l:"Report and tighten security",p:.85,w:{perf:10},wt:"Counterintelligence finds he's been contacted by insurgents.",f:{perf:-2},ft:"False alarm. Rapport takes a small hit."},{l:"Watch him yourself",p:.5,w:{perf:6},wt:"You catch him with a phone full of enemy contacts.",f:{wound:1},ft:"He opens fire during chow."},{l:"Dismiss it",p:.6,w:{lk:2},wt:"Nothing happens.",f:{wound:1,die:.15,cause:"killed in an insider attack"},ft:"Insider attack."}]},{t:"Drone Mishap",tier:"nco",i:"satellite",d:"Your team's small surveillance drone crashes in a market in {country}. Kids are already picking it up. What do you do?",c:[{l:"Go get it",p:.6,w:{perf:4},wt:"You trade candy for the drone. Diplomacy.",f:{perf:-8},ft:"A crowd forms. Tense moment, mission scrubbed."},{l:"Remotely wipe it",w:{perf:2},wt:"Data's gone. Kids get a cool toy."},{l:"Send the partner force",p:.7,w:{perf:6},wt:"They handle it smoothly.",f:{perf:-4},ft:"They 'lose' the drone. It ends up for sale."}]},{t:"Gunny's Retirement",tier:"nco",i:"medal",d:"Your old gunnery sergeant is retiring after 22 years. They ask you to give a speech. What kind of speech?",c:[{l:"Funny roast",p:.6,w:{rel:10},wt:"The whole room is crying laughing.",f:{rel:-5},ft:"One joke goes too far. His wife isn't laughing."},{l:"Heartfelt tribute",w:{rel:8,sm:2},wt:"The old man tears up for the first time ever."},{l:"Keep it short",w:{rel:3},wt:"He appreciates it. He hates speeches."}]},{t:"Instructor at ITC",tier:"nco",i:"trident",d:"You're now an ITC instructor. A student is talented but arrogant and dangerous on the range. Do you drop him?",c:[{l:"Drop him",w:{perf:4},wt:"Hard call. The right one."},{l:"Give him one more chance",p:.5,w:{perf:6},wt:"He gets humbled and becomes a great operator.",f:{perf:-8},ft:"He has a negligent discharge. Thankfully into the dirt."},{l:"Hand it to the board",w:{perf:2},wt:"The board drops him."}]},{t:"Old Wound Flares",tier:"nco",i:"stethoscope",d:"The shrapnel in your back starts acting up during a long ruck. You have miles left. What do you do?",c:[{l:"Stop and get checked",w:{he:3,perf:-2},wt:"Smart. Doc gives you meds and light duty."},{l:"Keep going",p:.5,w:{perf:4},wt:"You finish. It fades.",f:{he:-15},ft:"Something shifts. Surgery time."}]},{t:"Team Commander",tier:"officer",i:"star",d:"You take command of a Marine Special Operations Team. Your team chief has more combat experience than you. How do you lead?",c:[{l:"Listen first",w:{perf:10,rel:10},wt:"The team chief becomes your closest ally."},{l:"Assert authority",p:.4,w:{perf:5},wt:"The team respects your confidence.",f:{perf:-10,rel:-10},ft:"The team quietly decides you're a problem."},{l:"Lead from the front in PT",p:.7,w:{perf:8},wt:"You crush every workout. They notice.",f:{h:-5},ft:"You injure yourself trying too hard."}]},{t:"Mission Approval",tier:"officer",i:"radio",d:"Intelligence says a bomb-maker is at a house tonight. The approval chain will take 12 hours. You have the team ready now. What do you do?",c:[{l:"Wait for approval",w:{perf:2},wt:"By the time it's approved, he's gone. But you followed the rules."},{l:"Push for emergency approval",p:.6,w:{perf:12},wt:"Approved in an hour. Target captured.",f:{perf:-4},ft:"Denied. Higher wants more intel."},{l:"Go anyway",p:.3,w:{perf:10},wt:"Success. Nobody asks too many questions.",f:{court:"dereliction of duty",discharge:"general"},ft:"Investigated. Relieved of command."}]},{t:"Ambassador Meeting",tier:"officer",i:"flag",d:"The US ambassador in {country} is nervous about your team's operations. She wants fewer raids. How do you respond?",c:[{l:"Explain the mission",p:.7,w:{perf:8},wt:"She becomes a supporter.",f:{perf:-4},ft:"She calls your commander to complain."},{l:"Shift to training focus",w:{perf:4},wt:"Fewer raids, more partner growth. Everyone's happy."},{l:"Ignore her",w:{perf:-12},wt:"Your team gets restricted to base. Ouch."}]},{t:"Collateral Risk",tier:"officer",i:"bullseye",d:"A strike could kill a key militant leader, but there's a chance children are in the building. You have authority. What's your call?",c:[{l:"Hold the strike",w:{perf:-2,sm:4},wt:"He gets away. Later footage shows kids playing outside. You were right."},{l:"Order the strike",p:.5,w:{perf:10},wt:"Target killed. No civilians present.",f:{perf:-15,sm:-10},ft:"Civilians were inside. You'll carry this forever."},{l:"Get more surveillance",p:.6,w:{perf:8},wt:"He moves to a vehicle. Clean strike.",f:{perf:-4},ft:"He disappears into the city."}]},{t:"Officer Selection",tier:"officer",i:"trident",d:"As a Marine officer, you're screening for MARSOC. You'll have to compete with enlisted candidates in A&S. How do you approach it?",c:[{l:"Same standard as everyone",p:.7,w:{perf:10},wt:"Cadre respect it. You're selected.",f:{perf:-6},ft:"You're dropped. Try again next year."},{l:"Lead the team events",p:.6,w:{perf:12},wt:"Natural leader. Selected.",f:{perf:-4},ft:"Too bossy. Cadre aren't fans."}]},{t:"Media Interview",tier:"officer",i:"radio",d:"A journalist embedded with partner forces wants to interview you. Public affairs is unavailable. What do you do?",c:[{l:"Decline politely",w:{perf:2},wt:"No harm, no headlines."},{l:"Give a vague interview",p:.6,w:{perf:4},wt:"Story runs and makes partner forces look great.",f:{perf:-10},ft:"One quote is taken out of context. Huge headache."},{l:"Send your team chief",p:.3,w:{perf:2},wt:"He's surprisingly charming.",f:{perf:-8},ft:"He swears on the record. Many times."}]},{t:"Night Raid Gone Wrong",tier:"officer",i:"fire",d:"Midway through a raid, you realize the building is a wedding party, not a militant safehouse. Guests are panicking. What do you do?",c:[{l:"Withdraw immediately",w:{perf:4,sm:2},wt:"You apologize through interpreters. The elders appreciate it."},{l:"Search anyway",p:.3,w:{perf:6},wt:"You find a weapons cache under the floor.",f:{perf:-14},ft:"Nothing found. A diplomatic incident."},{l:"Call your commander",w:{perf:2},wt:"He orders an immediate exit. Smart."}]},{t:"Intel Leak",tier:"officer",i:"laptop",d:"You suspect someone in the partner force is leaking your mission plans to the enemy. How do you test it?",c:[{l:"Feed fake plans",p:.65,w:{perf:14},wt:"The enemy reacts to the fake plan. Leak found.",f:{perf:-4},ft:"The test is inconclusive."},{l:"Stop sharing plans",w:{perf:2},wt:"Safer, but partner trust drops."},{l:"Confront partner leaders",p:.4,w:{perf:8},wt:"They find the leak quickly.",f:{perf:-10},ft:"Deeply offended. Cooperation stalls."}]},{t:"Fitness Report",tier:"officer",i:"laptop",d:"Your commanding officer {co} wrote a mediocre fitness report that could hurt your promotion. You believe it's unfair. What do you do?",c:[{l:"Request a meeting",p:.6,w:{perf:6},wt:"He revises it after you show your results.",f:{perf:-4},ft:"He doesn't change a word."},{l:"File a rebuttal",p:.4,w:{perf:4},wt:"The reviewing officer sides with you.",f:{perf:-6},ft:"The rebuttal looks petty."},{l:"Accept it and work harder",w:{perf:3},wt:"Next year's report is glowing."}]},{t:"Plan the Big Op",tier:"officer",i:"map",d:"You're planning a multi-team operation in {country}. Your staff wants a complex plan. Your instincts say simple. What do you choose?",c:[{l:"Simple plan",p:.75,w:{perf:12},wt:"Everything goes smoothly. Simplicity wins.",f:{perf:-4},ft:"The enemy adapts faster than your simple plan."},{l:"Complex plan",p:.45,w:{perf:16},wt:"A brilliant multi-pronged success.",f:{perf:-10},ft:"Timing falls apart. Chaos."}]},{t:"Partner Force Graduation",tier:"officer",i:"flag",d:"The partner unit you trained graduates their first commando class. Their general wants you to speak. What's your message?",c:[{l:"Praise their soldiers",w:{perf:8},wt:"The soldiers chant your name. Their general beams."},{l:"Speak in their language",p:.5,w:{perf:12},wt:"The crowd erupts. Huge rapport.",f:{perf:-2},ft:"You accidentally insult someone's grandmother."},{l:"Keep it short",w:{perf:3},wt:"Professional and polite."}]},{t:"Staff Job",tier:"officer",i:"laptop",d:"You're offered a staff job at headquarters. It's great for promotion but you'd leave your team. What do you do?",c:[{l:"Take the staff job",w:{perf:10},wt:"Endless PowerPoint. Your career shines."},{l:"Stay with the team",w:{perf:-2,rel:8},wt:"The team appreciates it. HQ remembers."}]},{t:"Missing Teammate",tier:"officer",i:"radio",d:"During a night exfil, {buddy} is missing. The helicopter is waiting, and enemies are closing in. What do you do?",c:[{l:"Search for him",p:.6,w:{perf:14,rel:20},wt:"You find him with a broken leg. Everyone gets out.",f:{wound:1},ft:"You find him, but you're both hit on the way back."},{l:"Send a small team",p:.7,w:{perf:10,rel:10},wt:"They bring him back.",f:{perf:-8},ft:"They take casualties."},{l:"Leave without him",w:{perf:-20,sm:-15,rel:-30},wt:"Nobody gets left behind. Except today."}]},{t:"Ethical Dilemma",tier:"officer",i:"dagger",d:"A captured fighter claims he knows about an imminent attack. A partner officer suggests 'harsh methods'. What do you do?",c:[{l:"Forbid it",w:{perf:4,sm:3},wt:"Your interrogator gets the info through rapport."},{l:"Look away",p:.3,w:{perf:6},wt:"You get intel. You lose your soul a little.",f:{court:"detainee abuse",discharge:"dishonorable"},ft:"Investigation. Career over."},{l:"Report it",w:{perf:6},wt:"The partner officer is removed."}]},{t:"Budget Cut",tier:"officer",i:"recycle",d:"Your training budget is cut 40%. You must choose what to keep: dive training, sniper school, or language courses. What stays?",c:[{l:"Language",w:{perf:6},wt:"Your partner relationships thrive."},{l:"Dive",w:{perf:4},wt:"Maritime capability preserved."},{l:"Sniper",w:{perf:4},wt:"Precision fires stay sharp."}]},{t:"Helicopter Hard Landing",tier:"officer",i:"helicopter",d:"Your helicopter takes fire and does a hard landing. Everyone's alive but dazed. The enemy is coming. What do you do?",c:[{l:"Form a perimeter",p:.7,w:{perf:14},wt:"You hold until extraction.",f:{wound:1},ft:"You're hit organizing the perimeter."},{l:"Move to cover",p:.6,w:{perf:10},wt:"You reach a ridgeline and hold.",f:{wound:1},ft:"Ambushed on the way."}]},{t:"Married to the Job",tier:"officer",i:"flag",d:"You've missed three anniversaries and your spouse is moving out. {co} offers you leave right before an operation. What do you do?",c:[{l:"Take leave",w:{h:8,perf:-4},wt:"You save your marriage. The op goes fine without you."},{l:"Stay for the op",w:{perf:8,h:-10},wt:"The op is a success. Your house is empty."}]},{t:"Allied SOF Exchange",tier:"officer",i:"flag",d:"You're sent to train with a foreign special forces unit. Their methods are rough and their humor rougher. How do you fit in?",c:[{l:"Earn respect in training",p:.7,w:{perf:10},wt:"You outlast them on a march. Friends for life.",f:{h:-8},ft:"They push you past your limits. You end up in medical."},{l:"Bond over food",w:{perf:5,rel:5},wt:"Barbecue diplomacy works."}]},{t:"Battle of Wills",tier:"officer",i:"star",d:"Your battalion commander {co} wants to send your team into an operation you believe is poorly planned. What do you do?",c:[{l:"Raise concerns formally",p:.6,w:{perf:8},wt:"He adjusts the plan. Thanks you later.",f:{perf:-6},ft:"He takes it personally."},{l:"Execute as ordered",p:.5,w:{perf:6},wt:"It works out. You were wrong.",f:{wound:1},ft:"It goes exactly as badly as you feared."}]},{t:"Medal Recommendation",tier:"officer",i:"medal",d:"You must write award recommendations for your team. One Marine was brave but disliked by command. How do you write it?",c:[{l:"Write it honestly",w:{perf:4,sm:2},wt:"He gets his medal. Command grumbles."},{l:"Downgrade it",w:{perf:2,rel:-10},wt:"Command's happy. The team knows."}]},{t:"Captured Weapons Cache",tier:"officer",i:"bomb",d:"Your team finds a huge weapons cache. Some partner officers want to keep part of it. How do you handle it?",c:[{l:"Destroy it all",w:{perf:10},wt:"A huge explosion. The partner officers sulk."},{l:"Let them keep some",p:.4,w:{perf:4},wt:"It improves their capability.",f:{perf:-14},ft:"The weapons show up in enemy hands."}]},{t:"Pre-Mission Brief",tier:"officer",i:"map",d:"Your briefing to the task force commander has a typo putting your team 10 km from the real target. You notice mid-brief. What do you do?",c:[{l:"Correct it immediately",w:{perf:4},wt:"Commander appreciates the honesty."},{l:"Fix it later",p:.5,w:{perf:2},wt:"Nobody noticed.",f:{perf:-12},ft:"Air support plans around the wrong grid. Yikes."}]},{t:"Making Major",tier:"officer",i:"star",d:"The promotion board is reviewing your record. Your mentor offers to call a board member. What do you do?",c:[{l:"Decline",p:.6,w:{promote:1},wt:"Promoted on merit.",f:{perf:-2},ft:"Passed over this year."},{l:"Accept the call",p:.6,w:{promote:1,sm:-3},wt:"Promoted. You'll never know if it was fair.",f:{perf:-10},ft:"The board member reports it. Ugly."}]},{t:"Hostage Rescue",tier:"officer",i:"gun",d:"An aid worker is held hostage in {country}. Your team is ready. Intel says guards rotate at 0300. When do you hit?",c:[{l:"0300 rotation",p:.65,w:{perf:18,medal:"Bronze Star"},wt:"Hostage rescued alive. Zero friendly casualties.",f:{wound:1},ft:"The guards were alert. Heavy fighting."},{l:"Right now",p:.4,w:{perf:16},wt:"Surprise works. Hostage safe.",f:{perf:-10},ft:"The hostage is moved before you arrive."},{l:"Wait for more intel",p:.5,w:{perf:8},wt:"You find a better entry point. Success.",f:{perf:-12,sm:-6},ft:"The hostage is executed. Brutal."}]},{t:"Rules of Engagement",tier:"officer",i:"swords",d:"A partner commander wants your team to support an assault on a village. Your legal advisor says the target list is shaky. What's your call?",c:[{l:"Refuse to support",w:{perf:2,sm:3},wt:"The assault is canceled. Later, the list proves mostly wrong."},{l:"Support with limits",p:.6,w:{perf:8},wt:"You only engage confirmed fighters. Clean operation.",f:{perf:-8},ft:"The limits are ignored the moment shooting starts."},{l:"Full support",p:.3,w:{perf:10},wt:"The intel was right.",f:{perf:-16,sm:-8},ft:"Investigators arrive within a week."}]},{t:"Exhausted Team",tier:"officer",i:"tent",d:"Your team has run raids five nights straight. Higher wants one more tonight. Your Marines are making mistakes. What do you do?",c:[{l:"Request a rest night",p:.6,w:{perf:6,rel:10},wt:"Approved. The next raid is flawless.",f:{perf:-4},ft:"Denied. You go anyway, tired."},{l:"Go tonight",p:.5,w:{perf:8},wt:"Adrenaline carries you. Another success.",f:{wound:1},ft:"A tired mistake gets you hurt."}]},{t:"Maritime Interdiction",tier:"officer",i:"trident",d:"You lead a visit, board, search and seizure on a suspected weapons smuggling dhow at night. The crew is acting jumpy. How do you board?",c:[{l:"Fast and loud",p:.6,w:{perf:12},wt:"Crew surrenders instantly. Rockets found in the hold.",f:{wound:1},ft:"A crewman fires from the wheelhouse."},{l:"Hail and negotiate",p:.7,w:{perf:8},wt:"They comply. Weapons seized.",f:{perf:-6},ft:"They dump the cargo overboard while you talk."}]},{t:"Raider Regiment",tier:"senior",i:"eagle",d:"As {rank}, you command a Raider battalion. Congress wants MARSOC cut to save money. You're asked to testify. What do you emphasize?",c:[{l:"Partner-force success",p:.7,w:{perf:12},wt:"Budget saved. Senators praise the Raiders.",f:{perf:-4},ft:"The cuts go through anyway."},{l:"Combat record",p:.6,w:{perf:10},wt:"Strong testimony. Funding preserved.",f:{perf:-6},ft:"A senator calls it 'cowboy diplomacy'."}]},{t:"Battlefield Strategy",tier:"senior",i:"map",d:"You're asked to shift Raiders from counterterrorism to great-power competition. Some old operators resist. How do you lead the change?",c:[{l:"Explain the why",p:.75,w:{perf:12},wt:"The force adapts. History will thank you.",f:{perf:-4},ft:"Resistance slows it down."},{l:"Force it through",p:.5,w:{perf:8},wt:"Done quickly.",f:{perf:-10},ft:"Morale tanks. Retention drops."}]},{t:"Gold Star Family",tier:"senior",i:"flag",d:"You visit the family of a Raider killed under your command. His father is angry and blames you. What do you say?",c:[{l:"Listen and grieve with him",w:{sm:4},wt:"He calms down. You stay in touch for years."},{l:"Explain the mission",w:{sm:-2},wt:"He doesn't want to hear it. Not yet."}]},{t:"Scandal Brewing",tier:"senior",i:"policeman",d:"A news story reveals misconduct by Raiders under your command. Your boss wants to know how you'll respond. What's your plan?",c:[{l:"Full investigation",w:{perf:8},wt:"You clean house. Trust restored slowly."},{l:"Minimize it",p:.4,w:{perf:4},wt:"It blows over.",f:{perf:-20,demote:1},ft:"More stories come out. You're relieved."}]},{t:"Allied Summit",tier:"senior",i:"flag",d:"You represent US special operations at an allied summit. A foreign general proposes a joint mission with risky terms. What do you say?",c:[{l:"Agree with conditions",p:.7,w:{perf:10},wt:"A successful joint mission follows.",f:{perf:-6},ft:"The mission struggles on unclear command."},{l:"Decline",w:{perf:2},wt:"Relations cool, but risk avoided."}]},{t:"Retirement Call",tier:"senior",i:"medal",d:"After 26 years, you're being considered for general. Your body is wrecked and your family wants you home. What do you do?",c:[{l:"Go for general",p:.4,w:{promote:1},wt:"You pin on a star.",f:{perf:-4},ft:"Not selected. Time to plan retirement."},{l:"Retire",w:{h:10,discharge:"honorable"},wt:"You hang up the uniform with honors."}]},{t:"Raider Memorial",tier:"senior",i:"flag",d:"You're asked to dedicate a memorial for fallen Raiders, including some you sent into battle. What do you say?",c:[{l:"Read every name",w:{sm:5},wt:"It takes a long time. Nobody leaves."},{l:"Short speech",w:{sm:2},wt:"Dignified and brief."}]},{t:"Readiness Crisis",tier:"senior",i:"laptop",d:"Your battalion's injury rates are climbing and operators are burning out. Training tempo is to blame. What do you do?",c:[{l:"Cut the tempo",w:{perf:6,h:3},wt:"Injuries drop. Readiness actually improves."},{l:"Bring in performance staff",p:.7,w:{perf:10},wt:"Strength coaches and physical therapists work miracles.",f:{perf:-2},ft:"Funding for it gets denied."}]},{t:"Pentagon Briefing",tier:"senior",i:"eagle",d:"You brief senior leaders on a sensitive operation in {country}. One asks a question you can't answer. What do you do?",c:[{l:"'I'll find out'",w:{perf:4},wt:"Honesty is valued at this level."},{l:"Bluff",p:.4,w:{perf:2},wt:"Nobody catches it.",f:{perf:-12},ft:"Someone knows the real answer. Embarrassing."}]},{t:"Old Teammate Calls",tier:"senior",i:"radio",d:"A former Raider you served with as a captain calls you at midnight. He's out of the service and sounds like he's in crisis. What do you do?",c:[{l:"Drive to see him",w:{sm:6},wt:"You get him to a VA program. He's still alive years later."},{l:"Give him the crisis line",w:{sm:-2},wt:"He thanks you, flatly. You worry for weeks."}]},{t:"Family Reunion",tier:"any",i:"star",d:"At a family reunion, your uncle insists Raiders are just 'Navy SEAL wannabes'. Everyone is watching. What do you do?",c:[{l:"Explain politely",w:{sm:1},wt:"He doesn't listen, but your aunt is impressed."},{l:"Challenge him to push-ups",p:.9,w:{h:2},wt:"He taps out at 12. You do 80.",f:{h:-2},ft:"He pulls a muscle. Now it's your fault."},{l:"Let it go",w:{h:2},wt:"You eat potato salad in peace."}]},{t:"Lottery Ticket",tier:"any",i:"star",d:"{buddy} wants the team to pool money for a big lottery jackpot. Everyone's in. Are you?",c:[{l:"Throw in $20",p:.05,w:{money:25e3,rel:5},wt:"You actually win a small share!",f:{money:-20},ft:"Nothing. Of course."},{l:"Pass",w:{rel:-2},wt:"Nobody wins. You feel smug."}]},{t:"Movie Night",tier:"any",i:"star",d:"The team watches a military action movie. It's wildly inaccurate. {buddy} is yelling at the screen. Do you join in?",c:[{l:"Yell along",w:{rel:8,h:2},wt:"Best movie night ever."},{l:"Fact-check silently",w:{rel:2},wt:"You keep a mental list of errors."}]},{t:"Charity Ruck",tier:"any",i:"flag",d:"A Gold Star family organizes a memorial ruck. It's 22 miles on a weekend. Will you go?",c:[{l:"Do the ruck",w:{h:-2,sm:4},wt:"Your feet are destroyed. Your heart is full."},{l:"Donate instead",w:{money:-200,sm:2},wt:"The family sends a thank-you note."}]},{t:"Veterans Day",tier:"any",i:"flag",d:"A kid at a Veterans Day parade asks if you've ever been scared. What do you tell him?",c:[{l:"'All the time'",w:{sm:3},wt:"His dad nods. The kid looks amazed."},{l:"'Never'",w:{sm:-1},wt:"He thinks you're a superhero. It's a lie."}]},{t:"Gym Showdown",tier:"any",i:"helmet",d:"A local gym influencer challenges you to a pull-up contest on camera. Do you accept?",c:[{l:"Accept",p:.6,w:{sm:2},wt:"You win. The video goes viral.",f:{sm:-2},ft:"He wins. The video still goes viral."},{l:"Decline",w:{},wt:"No camera time. OPSEC intact."}]}];